(window.DOM_LAMLA=window.DOM_LAMLA||{})["circulation-3"]={"lecture":"circulation-3","chapters":[{"slug":"gravity","must":[{"star":true,"html":"<strong>Hydrostatic pressure</strong> increases below heart level and decreases above it because the vertical column of blood has weight."},{"star":false,"html":"<strong>Standing head pressure</strong> is about 60 mmHg (mean) because the head sits about 45 cm above the heart, so gravity removes about 35 mmHg."},{"star":false,"html":"<strong>Standing foot pressure</strong> is about 180 mmHg (mean) because the feet sit about 115 cm below the heart, so the blood column adds about 90 mmHg."},{"star":false,"html":"<strong>Leg vein pooling</strong> occurs on standing because compliant veins expand under increased hydrostatic pressure, trapping blood away from the heart."},{"star":true,"html":"<strong>Initial standing response</strong> reduces venous return → end-diastolic volume falls → stroke volume and cardiac output fall through Frank–Starling physiology."},{"star":false,"html":"<strong>Dependent oedema</strong> develops during prolonged standing because raised leg capillary hydrostatic pressure promotes fluid filtration into tissues."},{"star":false,"html":"<strong>Cerebral hypoperfusion</strong> causes light-headedness on standing because head-level arterial pressure and cardiac output initially decrease."},{"star":true,"html":"<strong>Baroreceptor unloading</strong> during standing reduces carotid sinus and aortic arch firing → sympathetic activity rises and vagal activity falls."},{"star":false,"html":"<strong>Positive chronotropy</strong> increases heart rate during standing because reduced vagal tone and greater sympathetic drive accelerate the SA node."},{"star":false,"html":"<strong>Positive inotropy</strong> strengthens ventricular contraction during standing because sympathetic stimulation raises cardiac contractility."},{"star":false,"html":"<strong>Arteriolar constriction</strong> raises total peripheral resistance during standing, helping restore arterial blood pressure."},{"star":false,"html":"<strong>Venoconstriction</strong> reduces peripheral blood storage → more blood returns to the heart and supports stroke volume."},{"star":true,"html":"<strong>Skeletal-muscle pump</strong> squeezes deep leg veins during walking; one-way valves direct blood upward and prevent pooling."},{"star":false,"html":"<strong>Renin–angiotensin–aldosterone</strong> supports pressure during sustained upright posture through vasoconstriction and renal sodium/water retention."},{"star":false,"html":"<strong>Cerebral perfusion gradient</strong> is partly preserved on standing because cerebral venous pressure decreases along with arterial pressure."},{"star":false,"html":"<strong>Falling intracranial pressure</strong> protects cerebral flow on standing because it reduces external compression of cerebral vessels."},{"star":false,"html":"<strong>Cerebral metabolic dilation</strong> responds to increased local CO₂ and reduced O₂ by widening brain arterioles and limiting flow loss."},{"star":false,"html":"<strong>Prolonged motionless standing</strong> weakens the muscle-pump defence → venous pooling worsens and cerebral flow may become insufficient."},{"star":false,"html":"<strong>Fainting after prolonged standing</strong> can restore cerebral perfusion because lying horizontally brings the head close to heart level."},{"star":false,"html":"<strong>Vasovagal syncope</strong> causes hypotension through sympathetic withdrawal and bradycardia through increased vagal activity."},{"star":false,"html":"<strong>Micturition syncope</strong> occurs during urination, often after rising at night, because reflex hypotension reduces cerebral blood flow."},{"star":false,"html":"<strong>Carotid sinus syncope</strong> follows pressure on a sensitive carotid sinus → reflex bradycardia and vasodilatation lower cerebral flow."},{"star":true,"html":"<strong>Orthostatic hypotension</strong> occurs when arterial pressure falls excessively after standing because compensatory sympathetic responses or circulating volume are inadequate."},{"star":false,"html":"<strong>Autonomic neuropathy</strong> causes orthostatic hypotension because damaged sympathetic nerves fail to constrict vessels appropriately, as in diabetes."},{"star":false,"html":"<strong>Sympatholytic drugs</strong> cause postural hypotension by preventing normal sympathetic vasoconstriction when blood pools in the legs."},{"star":false,"html":"<strong>Autonomic failure</strong> may prevent heart rate and plasma noradrenaline from rising on standing despite reduced arterial pressure."},{"star":false,"html":"<strong>Low blood volume</strong> worsens orthostatic hypotension because there is less circulating blood available to maintain venous return."},{"star":false,"html":"<strong>Positive acceleration (+g)</strong> shifts blood towards the feet → cerebral perfusion and retinal perfusion fall, causing grey-out or blackout."},{"star":false,"html":"<strong>Vision loss under high +g</strong> may precede unconsciousness because retinal perfusion fails when pressure at eye level becomes inadequate."},{"star":false,"html":"<strong>Negative acceleration (−g)</strong> shifts blood towards the head → congestion, headache, red-out and possible bleeding around the eyes."},{"star":false,"html":"<strong>Intracranial-pressure rise under −g</strong> helps protect cerebral vessels because venous congestion raises pressure outside them as arterial pressure rises."},{"star":false,"html":"<strong>Anti-g suits</strong> compress the abdomen and legs → peripheral pooling decreases and venous return rises during positive acceleration."},{"star":false,"html":"<strong>Horizontal positioning</strong> improves acceleration tolerance because the vertical blood column between the heart and brain becomes shorter."}],"numbers":"<table>\n<thead>\n<tr>\n  <th>Value</th>\n  <th>Number</th>\n  <th>Why it matters</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n  <td>Hydrostatic pressure change with height</td>\n  <td>About 0.77 mmHg per cm</td>\n  <td>Explains lower pressure above the heart and higher pressure below it.</td>\n</tr>\n<tr>\n  <td>Mean pressure at head level while standing</td>\n  <td>About 60 mmHg</td>\n  <td>Lecture illustration without compensation; pressure is lower than at the heart.</td>\n</tr>\n<tr>\n  <td>Mean pressure at heart level</td>\n  <td>About 93 mmHg</td>\n  <td>Corresponds to approximately 120/80 mmHg.</td>\n</tr>\n<tr>\n  <td>Mean pressure at feet while standing</td>\n  <td>About 180 mmHg</td>\n  <td>Demonstrates the added hydrostatic column below the heart.</td>\n</tr>\n<tr>\n  <td>Blood pooled on first standing</td>\n  <td>About 500 mL</td>\n  <td>Less blood is immediately available for venous return.</td>\n</tr>\n<tr>\n  <td>Usual rise in heart rate on standing</td>\n  <td>About 10–20 beats/min</td>\n  <td>Demonstrates baroreflex compensation.</td>\n</tr>\n<tr>\n  <td>Orthostatic systolic-pressure fall</td>\n  <td>At least 20 mmHg</td>\n  <td>One diagnostic criterion within 3 minutes of standing.</td>\n</tr>\n<tr>\n  <td>Orthostatic diastolic-pressure fall</td>\n  <td>At least 10 mmHg</td>\n  <td>Alternative diagnostic criterion within 3 minutes of standing.</td>\n</tr>\n<tr>\n  <td>Positive acceleration associated with severe cerebral underperfusion</td>\n  <td>Above about +5 g</td>\n  <td>Vision can fail, followed by blackout and unconsciousness.</td>\n</tr>\n</tbody>\n</table>\n","chains":"<ol>\n<li><strong>Standing and baroreflex rescue</strong>: Stand upright → leg veins expand and pool blood → venous return and cardiac output fall → baroreceptors fire less → sympathetic drive raises rate, contractility and vascular tone → arterial pressure recovers.</li>\n<li><strong>Protecting the brain</strong>: Head-level arterial pressure falls → cerebral venous and intracranial pressures also fall → local CO₂ rises and O₂ falls → cerebral arterioles dilate → cerebral flow is partly maintained.</li>\n<li><strong>Prolonged standing and syncope</strong>: Remain motionless → no leg-muscle pumping → venous pooling persists → cerebral perfusion falls → fainting places the head near heart level → cerebral perfusion improves.</li>\n<li><strong>Acceleration and countermeasures</strong>: Strong +g → blood shifts towards legs → retinal and cerebral flow fall → anti-g suit compresses abdomen and legs → pooling decreases → venous return and head-level perfusion improve.</li>\n</ol>\n","confuse":"<table>\n<thead>\n<tr>\n  <th></th>\n  <th><strong>Ordinary standing</strong></th>\n  <th><strong>Vasovagal syncope</strong></th>\n</tr>\n</thead>\n<tbody>\n<tr>\n  <td>Initial autonomic response</td>\n  <td>Sympathetic activity rises and vagal activity falls.</td>\n  <td>Sympathetic activity withdraws and vagal activity increases.</td>\n</tr>\n<tr>\n  <td>Typical heart-rate response</td>\n  <td>Heart rate rises to defend pressure.</td>\n  <td>Heart rate slows as blood pressure falls.</td>\n</tr>\n<tr>\n  <td>Main vascular response</td>\n  <td>Arterioles and veins constrict.</td>\n  <td>Widespread vasodilatation reduces pressure.</td>\n</tr>\n</tbody>\n</table>\n<table>\n<thead>\n<tr>\n  <th></th>\n  <th><strong>Orthostatic hypotension from autonomic failure</strong></th>\n  <th><strong>Normal baroreflex on standing</strong></th>\n</tr>\n</thead>\n<tbody>\n<tr>\n  <td>Sympathetic response</td>\n  <td>Insufficient vessel constriction; noradrenaline may fail to rise.</td>\n  <td>Vessel constriction and noradrenaline release increase.</td>\n</tr>\n<tr>\n  <td>Heart rate</td>\n  <td>May fail to increase appropriately.</td>\n  <td>Usually increases.</td>\n</tr>\n</tbody>\n</table>\n<table>\n<thead>\n<tr>\n  <th></th>\n  <th><strong>Positive g (+g)</strong></th>\n  <th><strong>Negative g (−g)</strong></th>\n</tr>\n</thead>\n<tbody>\n<tr>\n  <td>Blood redistribution</td>\n  <td>Towards the feet and abdomen.</td>\n  <td>Towards the head and neck.</td>\n</tr>\n<tr>\n  <td>Main danger</td>\n  <td>Low retinal/cerebral flow → grey-out, blackout.</td>\n  <td>Head congestion → red-out, headache.</td>\n</tr>\n<tr>\n  <td>Protective response</td>\n  <td>Anti-g suit and horizontal positioning reduce pooling.</td>\n  <td>Increased intracranial pressure partly opposes vessel distension.</td>\n</tr>\n</tbody>\n</table>\n","traps":"<ul>\n<li>Trap: <strong>Standing pressure</strong> is equal everywhere because the heart generates one pressure → Truth: Gravity adds or subtracts hydrostatic pressure according to height.</li>\n<li>Trap: <strong>Standing tachycardia</strong> means blood pressure initially rose → Truth: A pressure drop unloads baroreceptors, causing compensatory tachycardia.</li>\n<li>Trap: <strong>Brain protection</strong> occurs because cerebral arterial pressure never falls → Truth: Venous pressure, intracranial pressure and arteriolar resistance fall too.</li>\n<li>Trap: <strong>Prolonged standing</strong> is harmless if the person does not walk → Truth: Without the muscle pump, venous pooling can lead to fainting.</li>\n<li>Trap: <strong>Vasovagal fainting</strong> is simply a stronger sympathetic baroreflex → Truth: Sympathetic withdrawal and increased vagal firing produce vasodilatation and bradycardia.</li>\n<li>Trap: <strong>Orthostatic hypotension</strong> is diagnosed only by a low standing pressure → Truth: It is defined by a pressure fall after standing, within the specified time.</li>\n<li>Trap: <strong>Negative g</strong> causes the same blackout mechanism as positive g → Truth: Negative g shifts blood towards the head and produces congestion and red-out.</li>\n<li>Trap: <strong>Anti-g suits</strong> work by increasing heart muscle force directly → Truth: Abdominal and leg compression limits venous pooling and supports return.</li>\n</ul>\n"},{"slug":"shock","must":[{"star":true,"html":"<strong>Shock</strong> means tissue perfusion cannot sustain normal metabolism, so prolonged inadequacy causes cellular injury and organ dysfunction."},{"star":true,"html":"<strong>Normal early blood pressure</strong> does not exclude shock because sympathetic arteriolar constriction may temporarily maintain pressure despite poor tissue flow."},{"star":false,"html":"<strong>Hypovolaemic shock</strong> follows loss of blood or fluid → reduced circulating volume impairs venous return and cardiac output."},{"star":false,"html":"<strong>Cardiogenic shock</strong> follows pump failure → cardiac output decreases despite blood being present in the circulation."},{"star":false,"html":"<strong>Distributive shock</strong> follows widespread vasodilatation → blood pools and effective perfusion falls despite initially normal volume."},{"star":false,"html":"<strong>Obstructive shock</strong> follows blocked cardiac filling or forward blood flow → inadequate circulation reaches tissues."},{"star":true,"html":"<strong>Haemorrhage</strong> reduces blood volume → venous return falls → ventricular filling, stroke volume and cardiac output decrease."},{"star":false,"html":"<strong>Hypotension in haemorrhage</strong> develops because reduced cardiac output can no longer sustain arterial pressure despite compensation."},{"star":false,"html":"<strong>Reflex tachycardia</strong> follows lower baroreceptor stretch → sympathetic drive increases while vagal activity decreases."},{"star":false,"html":"<strong>Weak pulse in shock</strong> results from reduced stroke volume, even when sympathetic stimulation makes the heart beat faster."},{"star":false,"html":"<strong>Cool, pale skin</strong> occurs because sympathetic vasoconstriction restricts cutaneous blood flow to favour vital organs."},{"star":false,"html":"<strong>Low urine output</strong> reflects reduced renal perfusion and filtration, alongside sodium and water retention; blood urea may rise."},{"star":false,"html":"<strong>Rapid respiration</strong> occurs because hypoxia and lactic acidosis stimulate chemoreceptors and respiratory drive."},{"star":false,"html":"<strong>Thirst in shock</strong> increases as angiotensin II and ADH rise in response to reduced circulating volume."},{"star":false,"html":"<strong>Restlessness early in shock</strong> accompanies sympathetic arousal; later apathy may indicate cerebral ischaemia from prolonged hypoperfusion."},{"star":true,"html":"<strong>Lactic acidosis</strong> develops because inadequate oxygen delivery promotes anaerobic glycolysis; acidosis weakens the heart and vascular catecholamine responses."},{"star":false,"html":"<strong>Baroreflex compensation</strong> increases sympathetic cardiac stimulation, arteriolar resistance and venous return when arterial pressure falls."},{"star":false,"html":"<strong>Blood redistribution</strong> protects heart and brain relatively because constriction is stronger in skin, kidneys and splanchnic vessels."},{"star":false,"html":"<strong>Splanchnic venoconstriction</strong> mobilises stored blood → venous return improves temporarily when circulating blood volume falls."},{"star":false,"html":"<strong>Pulmonary venous mobilisation</strong> can shift stored blood towards systemic output, briefly supporting central filling during shock."},{"star":false,"html":"<strong>Adrenal medullary release</strong> of adrenaline and noradrenaline reinforces sympathetic cardiac and vascular compensation."},{"star":false,"html":"<strong>Renin–angiotensin–aldosterone activation</strong> promotes vasoconstriction and renal sodium/water retention, helping defend pressure and volume."},{"star":false,"html":"<strong>ADH (vasopressin)</strong> increases renal water retention and can constrict vessels, helping maintain circulation during volume loss."},{"star":false,"html":"<strong>ACTH and cortisol</strong> rise during shock as part of the endocrine stress response described in the lecture."},{"star":false,"html":"<strong>Interstitial-to-plasma refill</strong> occurs when capillary hydrostatic pressure falls → net fluid movement into blood helps restore volume."},{"star":false,"html":"<strong>Immediate haemoglobin concentration</strong> may remain normal after acute whole-blood loss because red cells and plasma are lost together."},{"star":false,"html":"<strong>Delayed haemoglobin fall</strong> follows tissue-fluid or infused-fluid replacement → red cells become diluted without immediate replacement."},{"star":false,"html":"<strong>Plasma protein dilution</strong> follows fluid restoration after bleeding because fluid returns faster than lost proteins are replaced."},{"star":false,"html":"<strong>Erythropoietin</strong> stimulates red-cell production over weeks, allowing haemoglobin to recover after haemorrhage."},{"star":true,"html":"<strong>Progressive shock</strong> becomes self-amplifying when poor perfusion injures the heart, brain vasomotor centre, kidneys and capillary circulation."},{"star":false,"html":"<strong>Myocardial ischaemia in shock</strong> reduces contractility → cardiac output falls further → coronary perfusion worsens."},{"star":false,"html":"<strong>Vasomotor-centre ischaemia</strong> eventually depresses sympathetic output → bradycardia and vasodilatation accelerate hypotension."},{"star":false,"html":"<strong>Acidosis in shock</strong> reduces cardiac function and responsiveness to catecholamines → compensatory vasoconstriction becomes ineffective."},{"star":false,"html":"<strong>Capillary stasis</strong> arises when precapillary sphincters relax but venules remain constricted → pressure rises and fluid leaks into tissues."},{"star":false,"html":"<strong>Acute tubular damage</strong> may follow prolonged renal hypoperfusion, worsening organ failure during severe shock."},{"star":false,"html":"<strong>Irreversible shock</strong> persists despite correction of blood volume because severe tissue damage prevents circulatory recovery."},{"star":false,"html":"<strong>Concealed haemorrhage</strong> may occur with femoral fracture, ruptured spleen or ectopic pregnancy despite absent external bleeding."},{"star":false,"html":"<strong>Burn shock</strong> causes plasma loss through damaged skin → haemoconcentration can increase haematocrit rather than decrease it."},{"star":false,"html":"<strong>Traumatic muscle injury</strong> releases myoglobin, which can damage renal tubules and worsen shock complications."},{"star":false,"html":"<strong>Cardiogenic shock</strong> may cause raised venous pressure and jugular venous pressure because blood backs up behind the failing heart."},{"star":false,"html":"<strong>Septic shock</strong> involves bacterial toxins, widespread vasodilatation and capillary leak; skin may feel warm early."},{"star":false,"html":"<strong>Anaphylactic shock</strong> follows histamine release during an antigen–antibody response → vasodilatation and increased capillary permeability."},{"star":false,"html":"<strong>Neurogenic shock</strong> follows loss of sympathetic vascular tone → low peripheral resistance, sometimes with bradycardia."},{"star":false,"html":"<strong>Cardiac tamponade</strong> impairs cardiac filling through external compression → obstructive shock reduces forward output."},{"star":false,"html":"<strong>Tension pneumothorax</strong> can compress great veins and impair return to the heart → obstructive shock develops."},{"star":false,"html":"<strong>Pulmonary embolism</strong> blocks pulmonary arterial flow → right-sided outflow obstruction reduces circulation through the lungs."}],"numbers":"<table>\n<thead>\n<tr>\n  <th>Value</th>\n  <th>Number</th>\n  <th>Why it matters</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n  <td>Approximate blood-volume recovery if bleeding stops</td>\n  <td>12–72 hours</td>\n  <td>Fluid shift and renal retention restore volume before red cells are fully replaced.</td>\n</tr>\n<tr>\n  <td>Approximate haemoglobin recovery after blood loss</td>\n  <td>4–5 weeks</td>\n  <td>Renal erythropoietin drives red-cell replacement over weeks.</td>\n</tr>\n<tr>\n  <td>Blood concealed by a fractured femur</td>\n  <td>More than 1 litre may be hidden</td>\n  <td>External inspection can underestimate serious blood loss.</td>\n</tr>\n</tbody>\n</table>\n","chains":"<ol>\n<li><strong>Haemorrhagic shock</strong>: Whole-blood loss → venous return falls → end-diastolic volume and stroke volume fall → cardiac output and organ perfusion decrease → sympathetic reflexes attempt compensation.</li>\n<li><strong>Metabolic deterioration</strong>: Tissue perfusion falls → oxygen delivery becomes inadequate → anaerobic glycolysis produces lactate → acidosis weakens myocardium and vascular catecholamine responses → perfusion falls further.</li>\n<li><strong>Volume recovery versus haemoglobin recovery</strong>: Bleeding stops → capillary fluid refill and salt/water retention restore plasma volume → haemoglobin concentration falls by dilution → erythropoietin restores red cells over weeks.</li>\n<li><strong>Irreversible progression</strong>: Prolonged hypoperfusion → cardiac and vasomotor-centre ischaemia plus capillary stasis → further hypotension and fluid loss → cellular injury persists despite later volume replacement.</li>\n</ol>\n","confuse":"<table>\n<thead>\n<tr>\n  <th></th>\n  <th><strong>Hypovolaemic shock</strong></th>\n  <th><strong>Cardiogenic shock</strong></th>\n</tr>\n</thead>\n<tbody>\n<tr>\n  <td>Primary defect</td>\n  <td>Blood/fluid volume is depleted.</td>\n  <td>Pump function is inadequate.</td>\n</tr>\n<tr>\n  <td>Venous filling pressure</td>\n  <td>Usually low after blood loss.</td>\n  <td>May be high because blood backs up.</td>\n</tr>\n<tr>\n  <td>Examples</td>\n  <td>Haemorrhage, burns, severe diarrhoea.</td>\n  <td>Myocardial infarction, heart failure, arrhythmia.</td>\n</tr>\n</tbody>\n</table>\n<table>\n<thead>\n<tr>\n  <th></th>\n  <th><strong>Distributive shock</strong></th>\n  <th><strong>Obstructive shock</strong></th>\n</tr>\n</thead>\n<tbody>\n<tr>\n  <td>Primary defect</td>\n  <td>Widespread vessel dilation and pooling.</td>\n  <td>Physical blockage to filling or flow.</td>\n</tr>\n<tr>\n  <td>Examples</td>\n  <td>Sepsis, anaphylaxis, neurogenic shock.</td>\n  <td>Tamponade, tension pneumothorax, pulmonary embolism.</td>\n</tr>\n</tbody>\n</table>\n<table>\n<thead>\n<tr>\n  <th></th>\n  <th><strong>Acute whole-blood haemorrhage</strong></th>\n  <th><strong>Burn-related plasma loss</strong></th>\n</tr>\n</thead>\n<tbody>\n<tr>\n  <td>What is lost</td>\n  <td>Red cells and plasma together.</td>\n  <td>Mainly plasma through injured skin.</td>\n</tr>\n<tr>\n  <td>Early haemoglobin/haematocrit</td>\n  <td>Concentration may be initially unchanged.</td>\n  <td>Concentration may rise due to haemoconcentration.</td>\n</tr>\n<tr>\n  <td>Later course</td>\n  <td>Fluid replacement dilutes remaining red cells.</td>\n  <td>Fluid loss persists until corrected.</td>\n</tr>\n</tbody>\n</table>\n<table>\n<thead>\n<tr>\n  <th></th>\n  <th><strong>Compensated shock</strong></th>\n  <th><strong>Irreversible shock</strong></th>\n</tr>\n</thead>\n<tbody>\n<tr>\n  <td>Circulatory responses</td>\n  <td>Sympathetic and hormonal responses still partly defend perfusion.</td>\n  <td>Heart, central vasomotor and microvascular damage prevent recovery.</td>\n</tr>\n<tr>\n  <td>Blood pressure</td>\n  <td>May appear near normal early.</td>\n  <td>Usually severely reduced despite attempted correction.</td>\n</tr>\n</tbody>\n</table>\n","traps":"<ul>\n<li>Trap: <strong>Shock</strong> requires a very low measured blood pressure → Truth: Tissue perfusion may already be inadequate while vasoconstriction temporarily preserves pressure.</li>\n<li>Trap: <strong>Tachycardia</strong> proves adequate cardiac output → Truth: A rapid heart can still eject too little blood per beat.</li>\n<li>Trap: <strong>A normal initial haemoglobin</strong> excludes major bleeding → Truth: Whole blood loss preserves concentration until fluid redistribution causes dilution.</li>\n<li>Trap: <strong>Burn shock</strong> must initially lower haematocrit → Truth: Plasma escapes while red cells remain, causing haemoconcentration.</li>\n<li>Trap: <strong>Renal oliguria</strong> is only caused by dehydration → Truth: Reduced renal perfusion, lower filtration and hormonal sodium/water retention contribute.</li>\n<li>Trap: <strong>All shock patients</strong> have cold skin → Truth: Early septic shock may produce warm skin because cutaneous vessels are dilated.</li>\n<li>Trap: <strong>Compensation</strong> restores oxygen delivery completely → Truth: Prioritising brain and heart can coexist with severe kidney, skin and gut hypoperfusion.</li>\n<li>Trap: <strong>Capillary filtration</strong> must keep falling throughout shock → Truth: Late precapillary relaxation with venular constriction causes stasis and increased leakage.</li>\n<li>Trap: <strong>Irreversible shock</strong> means blood volume cannot be replaced → Truth: Circulation fails to recover even after volume is restored because tissues are damaged.</li>\n<li>Trap: <strong>Obstructive shock</strong> is simply vasodilatation → Truth: Tamponade, tension pneumothorax or embolism physically impedes blood flow.</li>\n</ul>\n"},{"slug":"heart-failure","must":[{"star":true,"html":"<strong>Heart failure</strong> occurs when the heart cannot meet tissue needs, or does so only at abnormally high filling pressures."},{"star":false,"html":"<strong>Near-normal resting cardiac output</strong> does not exclude failure because excessive ventricular filling pressure can sustain output while causing congestion."},{"star":true,"html":"<strong>Forward failure</strong> reduces blood delivered to organs → poor perfusion causes fatigue, exercise intolerance and renal sodium/water retention."},{"star":true,"html":"<strong>Backward failure</strong> raises pressure upstream of a failing chamber → venous congestion and fluid accumulation develop."},{"star":false,"html":"<strong>Systolic failure</strong> reflects weak ventricular contraction → reduced ejection fraction and increased residual ventricular blood."},{"star":false,"html":"<strong>Diastolic failure</strong> reflects impaired relaxation or stiff ventricles → high filling pressures despite often-preserved ejection fraction."},{"star":false,"html":"<strong>Preserved ejection fraction</strong> does not exclude failure because a stiff ventricle may eject a normal fraction of a small filling volume."},{"star":false,"html":"<strong>Both systolic and diastolic failure</strong> can cause congestion because ventricular filling pressure rises in either condition."},{"star":false,"html":"<strong>Tachycardia in a stiff ventricle</strong> worsens filling because diastolic time shortens while the chamber already fills slowly."},{"star":true,"html":"<strong>Left-sided backward failure</strong> raises left atrial and pulmonary venous pressure → pulmonary capillary filtration increases and pulmonary oedema develops."},{"star":false,"html":"<strong>Pulmonary oedema</strong> impairs gas exchange → breathlessness and rapid breathing may accompany left ventricular failure."},{"star":false,"html":"<strong>Orthopnoea</strong> occurs because lying flat returns leg blood to the chest → a weak left ventricle cannot handle the extra filling."},{"star":true,"html":"<strong>Right-sided backward failure</strong> raises systemic venous pressure → jugular distension, liver congestion, ascites and dependent oedema develop."},{"star":false,"html":"<strong>Jugular venous pressure</strong> rises in right-sided failure because impaired right ventricular emptying increases right atrial pressure."},{"star":false,"html":"<strong>Hepatomegaly and ascites</strong> follow systemic venous congestion because hepatic pressure rises and abdominal fluid accumulates."},{"star":false,"html":"<strong>Ankle oedema</strong> develops in right-sided failure because raised peripheral venous pressure increases capillary filtration."},{"star":false,"html":"<strong>Left-heart failure</strong> commonly leads to right-heart failure because sustained pulmonary pressure increases right ventricular workload."},{"star":false,"html":"<strong>Sympathetic compensation</strong> raises heart rate, contractility and resistance → pressure may improve briefly but afterload and workload increase."},{"star":false,"html":"<strong>Renin–angiotensin–aldosterone activation</strong> constricts vessels and retains sodium/water → initial perfusion support worsens long-term congestion."},{"star":false,"html":"<strong>ADH release</strong> promotes renal water retention → fluid overload can increase despite already swollen tissues."},{"star":false,"html":"<strong>Effective arterial underfilling</strong> stimulates renal fluid retention because a weak pump delivers too little pressure even when total body water is high."},{"star":false,"html":"<strong>Frank–Starling limitation</strong> means extra filling of a failing ventricle raises pressure more than output because its function curve is flattened."},{"star":false,"html":"<strong>Cardiac remodelling</strong> can thicken or dilate a chronically stressed ventricle → pumping efficiency deteriorates over time."}],"numbers":"","chains":"<ol>\n<li><strong>Left-sided backward failure</strong>: Left ventricle empties poorly → left atrial and lung venous pressures rise → pulmonary capillary filtration increases → pulmonary oedema develops → breathlessness worsens.</li>\n<li><strong>Right-sided backward failure</strong>: Right ventricle empties poorly → right atrial/systemic venous pressure rises → jugular veins distend and capillary filtration increases → liver congestion, ascites and ankle oedema develop.</li>\n<li><strong>Maladaptive compensation</strong>: Pump output falls → baroreceptors and kidneys perceive arterial underfilling → sympathetic, RAAS and ADH activity rise → afterload and fluid retention increase → ventricular failure and oedema worsen.</li>\n<li><strong>Frank–Starling failure</strong>: Ventricular filling volume increases → failing ventricular muscle provides little extra ejection → filling pressure rises disproportionately → upstream venous congestion increases.</li>\n</ol>\n","confuse":"<table>\n<thead>\n<tr>\n  <th></th>\n  <th><strong>Forward failure</strong></th>\n  <th><strong>Backward failure</strong></th>\n</tr>\n</thead>\n<tbody>\n<tr>\n  <td>Main problem</td>\n  <td>Too little blood reaches downstream tissues.</td>\n  <td>Too much blood/pressure builds up upstream.</td>\n</tr>\n<tr>\n  <td>Clinical consequence</td>\n  <td>Fatigue and poor organ perfusion.</td>\n  <td>Pulmonary or systemic venous congestion.</td>\n</tr>\n</tbody>\n</table>\n<table>\n<thead>\n<tr>\n  <th></th>\n  <th><strong>Left-sided failure</strong></th>\n  <th><strong>Right-sided failure</strong></th>\n</tr>\n</thead>\n<tbody>\n<tr>\n  <td>Where blood backs up</td>\n  <td>Pulmonary veins and lungs.</td>\n  <td>Systemic veins, liver and legs.</td>\n</tr>\n<tr>\n  <td>Characteristic signs</td>\n  <td>Breathlessness, orthopnoea, pulmonary oedema.</td>\n  <td>Raised JVP, hepatomegaly, ascites, ankle oedema.</td>\n</tr>\n</tbody>\n</table>\n<table>\n<thead>\n<tr>\n  <th></th>\n  <th><strong>Systolic dysfunction</strong></th>\n  <th><strong>Diastolic dysfunction</strong></th>\n</tr>\n</thead>\n<tbody>\n<tr>\n  <td>Principal mechanical defect</td>\n  <td>Weak contraction and poor ejection.</td>\n  <td>Impaired relaxation or stiff filling.</td>\n</tr>\n<tr>\n  <td>Ejection fraction</td>\n  <td>Usually reduced.</td>\n  <td>Often preserved.</td>\n</tr>\n<tr>\n  <td>Filling pressure</td>\n  <td>Rises because blood is left behind.</td>\n  <td>Rises because a stiff ventricle needs higher pressure to fill.</td>\n</tr>\n</tbody>\n</table>\n","traps":"<ul>\n<li>Trap: <strong>Heart failure</strong> always means low cardiac output at rest → Truth: Output may appear adequate only because filling pressures are abnormally high.</li>\n<li>Trap: <strong>Preserved ejection fraction</strong> means the ventricle is healthy → Truth: A stiff ventricle can eject a normal proportion but fill at excessive pressure.</li>\n<li>Trap: <strong>Left failure</strong> primarily raises systemic venous pressure → Truth: Its characteristic backward effect is increased pulmonary venous pressure and oedema.</li>\n<li>Trap: <strong>Right failure</strong> primarily causes pulmonary oedema → Truth: Right-sided backward failure produces systemic venous congestion, raised JVP and dependent oedema.</li>\n<li>Trap: <strong>Lying flat</strong> relieves all heart-failure breathlessness → Truth: Greater venous return can worsen pulmonary congestion when the left ventricle fails.</li>\n<li>Trap: <strong>Renal salt retention</strong> indicates total-body dehydration → Truth: Effective arterial delivery may be low despite substantial whole-body fluid overload.</li>\n<li>Trap: <strong>More preload</strong> always substantially raises cardiac output → Truth: A failing ventricle may gain little output while filling pressure and congestion rise.</li>\n</ul>\n"}]};
